from concurrent.futures import ThreadPoolExecutor

import pytest


def square(x: int) -> int:
    return x * x


def sum_squares_workers(xs: list[int], workers: int) -> int:
    """Sum of squares of xs, computing each square via `square` in a
    thread pool with `workers` threads.

    The result is exact (integer addition is associative) and therefore
    identical for every worker count. Empty input returns 0.
    Raises ValueError if workers < 1.
    """
    if workers < 1:
        raise ValueError("workers must be >= 1")
    if not xs:
        return 0
    with ThreadPoolExecutor(max_workers=workers) as pool:
        squares = list(pool.map(square, xs))
    return sum(squares)


def sum_squares(xs: list[int]) -> int:
    """Sum of squares of every element of xs, computed in parallel
    with a thread pool using a default worker count."""
    return sum_squares_workers(xs, 4)


WORKER_COUNTS = [1, 2, 3, 4, 8, 16]


def test_sum_squares_basic() -> None:
    assert sum_squares([1, 2, 3]) == 14
    assert sum_squares([-3, 3]) == 18
    assert sum_squares([0, 0]) == 0


def test_sum_squares_empty_and_single() -> None:
    assert sum_squares([]) == 0
    assert sum_squares([7]) == 49
    assert sum_squares([-7]) == 49


def test_sum_squares_big_ints() -> None:
    big = 10**20
    assert sum_squares([big, -big]) == 2 * big * big


@pytest.mark.parametrize("workers", WORKER_COUNTS)
def test_same_result_at_every_worker_count(workers: int) -> None:
    xs = list(range(-100, 101))
    expected = sum(x * x for x in xs)
    assert sum_squares_workers(xs, workers) == expected


@pytest.mark.parametrize("workers", WORKER_COUNTS)
def test_workers_more_than_elements(workers: int) -> None:
    assert sum_squares_workers([], workers) == 0
    assert sum_squares_workers([5], workers) == 25
    assert sum_squares_workers([1, 2], workers) == 5


def test_all_worker_counts_agree_on_large_input() -> None:
    xs = [(i * 7919) % 1009 - 500 for i in range(5000)]
    results = {sum_squares_workers(xs, w) for w in WORKER_COUNTS}
    assert results == {sum(x * x for x in xs)}
    assert sum_squares(xs) in results


def test_input_not_mutated() -> None:
    xs = [3, -1, 2]
    copy = list(xs)
    sum_squares(xs)
    assert xs == copy


@pytest.mark.parametrize("workers", [0, -1])
def test_invalid_worker_count(workers: int) -> None:
    with pytest.raises(ValueError):
        sum_squares_workers([1, 2, 3], workers)
